// 修復負担を候補順位へ反映する強さ。探索条件はv073の実験ノートを参照する。
#ifndef AHC072_REPAIR_WEIGHT
#define AHC072_REPAIR_WEIGHT 1.0
#endif
constexpr double repair_weight = AHC072_REPAIR_WEIGHT;
static_assert(0.0 <= repair_weight && repair_weight <= 2.5);

new:
// 修復係数は指定値に固定する。他の6項目だけを同じ新規入力で調整する。
constexpr double repair_weight = 0.83;
#ifndef AHC072_SIZE_EXPONENT
#define AHC072_SIZE_EXPONENT 0.65
#endif
constexpr double removal_size_exponent = AHC072_SIZE_EXPONENT;
static_assert(0.35 <= removal_size_exponent && removal_size_exponent <= 0.95);
#ifndef AHC072_NOISE_AMPLITUDE
#define AHC072_NOISE_AMPLITUDE 0.10
#endif
constexpr double priority_noise_amplitude = AHC072_NOISE_AMPLITUDE;
static_assert(0.0 <= priority_noise_amplitude && priority_noise_amplitude <= 0.30);
#ifndef AHC072_START_TEMPERATURE
#define AHC072_START_TEMPERATURE 0.70
#endif
constexpr double lns_start_temperature = AHC072_START_TEMPERATURE;
static_assert(0.30 <= lns_start_temperature && lns_start_temperature <= 1.25);
#ifndef AHC072_END_TEMPERATURE
#define AHC072_END_TEMPERATURE 0.08
#endif
constexpr double lns_end_temperature = AHC072_END_TEMPERATURE;
static_assert(0.02 <= lns_end_temperature && lns_end_temperature <= 0.20);
#ifndef AHC072_DEPENDENCY_INTERVAL
#define AHC072_DEPENDENCY_INTERVAL 4
#endif
constexpr int dependency_interval = AHC072_DEPENDENCY_INTERVAL;
static_assert(2 <= dependency_interval && dependency_interval <= 8);
#ifndef AHC072_COOLDOWN_FRACTION
#define AHC072_COOLDOWN_FRACTION 0.50
#endif
constexpr double regular_cooldown_fraction = AHC072_COOLDOWN_FRACTION;
static_assert(0.125 <= regular_cooldown_fraction && regular_cooldown_fraction <= 1.0);
static_assert(lns_end_temperature < lns_start_temperature);
